import { Method, type MatrixHttpApi } from "../../http-api/index.ts";
import type { IHttpOpts } from "../../http-api/index.ts";
import type { IRoomEvent } from "../../sync-accumulator.ts";
import type { IContent } from "../../models/event.ts";
import type { EmptyObject } from "../../@types/common.ts";

export interface MessageProcessorEvents {
    messageSent: { roomId: string; eventId: string; content: IContent };
    messageReceived: { roomId: string; event: IRoomEvent };
    error: Error;
}

export interface SendMessageOptions {
    txnId?: string;
    eventType?: string;
}

export interface GetMessagesOptions {
    from?: string;
    to?: string;
    dir?: "f" | "b";
    limit?: number;
    filter?: Record<string, unknown>;
}

export interface MessagesResponse {
    start: string;
    end: string;
    chunk: IRoomEvent[];
    state?: IRoomEvent[];
}

export interface EventContextResponse {
    start: string;
    end: string;
    events_before: IRoomEvent[];
    event: IRoomEvent;
    events_after: IRoomEvent[];
    state?: IRoomEvent[];
}

export class MessageProcessor {
    private pendingMessages: Map<string, Promise<string>> = new Map();
    private messageQueue: Map<string, IRoomEvent[]> = new Map();

    public constructor(private http: MatrixHttpApi<IHttpOpts>) {}

    public async sendMessage(roomId: string, content: IContent, options: SendMessageOptions = {}): Promise<string> {
        const txnId = options.txnId || this.generateTxnId();
        const eventType = options.eventType || "m.room.message";

        const key = `${roomId}:${txnId}`;

        if (this.pendingMessages.has(key)) {
            return this.pendingMessages.get(key)!;
        }

        const promise = this.sendEvent(roomId, eventType, content, txnId);
        this.pendingMessages.set(key, promise);

        try {
            const eventId = await promise;
            return eventId;
        } finally {
            this.pendingMessages.delete(key);
        }
    }

    public async sendTextMessage(roomId: string, text: string, txnId?: string): Promise<string> {
        return this.sendMessage(
            roomId,
            {
                msgtype: "m.text",
                body: text,
            },
            { txnId },
        );
    }

    public async sendHtmlMessage(roomId: string, html: string, text: string, txnId?: string): Promise<string> {
        return this.sendMessage(
            roomId,
            {
                msgtype: "m.text",
                body: text,
                format: "org.matrix.custom.html",
                formatted_body: html,
            },
            { txnId },
        );
    }

    public async sendEmote(roomId: string, text: string, txnId?: string): Promise<string> {
        return this.sendMessage(
            roomId,
            {
                msgtype: "m.emote",
                body: text,
            },
            { txnId },
        );
    }

    public async sendNotice(roomId: string, text: string, txnId?: string): Promise<string> {
        return this.sendMessage(
            roomId,
            {
                msgtype: "m.notice",
                body: text,
            },
            { txnId },
        );
    }

    public async sendImage(
        roomId: string,
        url: string,
        info?: Record<string, unknown>,
        text?: string,
        txnId?: string,
    ): Promise<string> {
        return this.sendMessage(
            roomId,
            {
                msgtype: "m.image",
                url,
                body: text || "Image",
                info,
            },
            { txnId },
        );
    }

    public async sendVideo(
        roomId: string,
        url: string,
        info?: Record<string, unknown>,
        text?: string,
        txnId?: string,
    ): Promise<string> {
        return this.sendMessage(
            roomId,
            {
                msgtype: "m.video",
                url,
                body: text || "Video",
                info,
            },
            { txnId },
        );
    }

    public async sendAudio(
        roomId: string,
        url: string,
        info?: Record<string, unknown>,
        text?: string,
        txnId?: string,
    ): Promise<string> {
        return this.sendMessage(
            roomId,
            {
                msgtype: "m.audio",
                url,
                body: text || "Audio",
                info,
            },
            { txnId },
        );
    }

    public async sendFile(
        roomId: string,
        url: string,
        info?: Record<string, unknown>,
        text?: string,
        txnId?: string,
    ): Promise<string> {
        return this.sendMessage(
            roomId,
            {
                msgtype: "m.file",
                url,
                body: text || "File",
                info,
            },
            { txnId },
        );
    }

    public async sendLocation(roomId: string, geoUri: string, text?: string, txnId?: string): Promise<string> {
        return this.sendMessage(
            roomId,
            {
                msgtype: "m.location",
                geo_uri: geoUri,
                body: text || "Location",
            },
            { txnId },
        );
    }

    public async sendReaction(roomId: string, eventId: string, emoji: string, txnId?: string): Promise<string> {
        return this.sendEvent(
            roomId,
            "m.reaction",
            {
                "m.relates_to": {
                    rel_type: "m.annotation",
                    event_id: eventId,
                    key: emoji,
                },
            },
            txnId ?? this.generateTxnId(),
        );
    }

    public async redactEvent(roomId: string, eventId: string, reason?: string, txnId?: string): Promise<string> {
        const path = `/rooms/${roomId}/redact/${encodeURIComponent(eventId)}`;
        const body: Record<string, unknown> = {};
        if (reason) {
            body.reason = reason;
        }

        const response = await this.http.authedRequest<{ event_id: string }>(
            Method.Put,
            `${path}/${txnId || this.generateTxnId()}`,
            undefined,
            body,
        );

        return response.event_id;
    }

    public async getRoomMessages(roomId: string, options: GetMessagesOptions = {}): Promise<MessagesResponse> {
        return this.http.authedRequest<MessagesResponse>(
            Method.Get,
            `/rooms/${roomId}/messages`,
            options as Record<string, string | string[]>,
        );
    }

    public async getEventContext(roomId: string, eventId: string, limit?: number): Promise<EventContextResponse> {
        return this.http.authedRequest(Method.Get, `/rooms/${roomId}/context/${encodeURIComponent(eventId)}`, {
            limit,
        });
    }

    public async setReadReceipt(
        roomId: string,
        eventId: string,
        receiptType: "m.read" | "m.read.private" = "m.read",
    ): Promise<void> {
        await this.http.authedRequest(
            Method.Post,
            `/rooms/${roomId}/receipt/${receiptType}/${encodeURIComponent(eventId)}`,
        );
    }

    public async setReadMarkers(
        roomId: string,
        options: {
            "m_read"?: string;
            "m.fully_read"?: string;
            "m.read.private"?: string;
        },
    ): Promise<EmptyObject> {
        return this.http.authedRequest(Method.Post, `/rooms/${roomId}/read_markers`, undefined, options);
    }

    public async setTyping(roomId: string, isTyping: boolean, timeout?: number): Promise<EmptyObject> {
        const userId = (this.http.opts as { userId?: string }).userId;
        if (!userId) {
            throw new Error("User ID not set");
        }
        return this.http.authedRequest(Method.Put, `/rooms/${roomId}/typing/${encodeURIComponent(userId)}`, undefined, {
            typing: isTyping,
            timeout,
        });
    }

    public queueMessage(roomId: string, event: IRoomEvent): void {
        if (!this.messageQueue.has(roomId)) {
            this.messageQueue.set(roomId, []);
        }
        this.messageQueue.get(roomId)!.push(event);
    }

    public getQueuedMessages(roomId: string): IRoomEvent[] {
        return this.messageQueue.get(roomId) || [];
    }

    public clearQueuedMessages(roomId: string): void {
        this.messageQueue.delete(roomId);
    }

    private async sendEvent(roomId: string, eventType: string, content: IContent, txnId: string): Promise<string> {
        const response = await this.http.authedRequest<{ event_id: string }>(
            Method.Put,
            `/rooms/${roomId}/send/${eventType}/${txnId}`,
            undefined,
            content,
        );

        return response.event_id;
    }

    private generateTxnId(): string {
        return `txn_${Date.now()}_${Math.random().toString(36).substring(2, 11)}`;
    }
}
